WHENEVER SQLERROR EXIT SQL.SQLCODE;

PROMPT Creating DEV_TEMPLATE.HR_PAYROLL_ADJUSTMENT table...

BEGIN
    EXECUTE IMMEDIATE '
    CREATE TABLE "DEV_TEMPLATE"."HR_PAYROLL_ADJUSTMENT" (
        "ID" NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
        "COMPANY_ID" NUMBER(19) NOT NULL,
        "EMPLOYEE_CODE" NVARCHAR2(100) NOT NULL,
        "PAY_PERIOD" NVARCHAR2(40) NOT NULL,
        "COMPONENT_CODE" NVARCHAR2(100) NOT NULL,
        "ADJUSTMENT_TYPE" NVARCHAR2(20) NOT NULL,
        "AMOUNT" NUMBER(18, 4) NOT NULL,
        "DESCRIPTION" NVARCHAR2(500) NULL,
        "STATUS" NVARCHAR2(20) DEFAULT ''APPROVED'' NOT NULL,
        "PAYROLL_RUN_LINE_ID" NUMBER(19) NULL,
        "CREATION_USER" NVARCHAR2(200) NOT NULL,
        "CREATION_DATE" TIMESTAMP(7) DEFAULT CURRENT_TIMESTAMP NOT NULL,
        "UPDATE_USER" NVARCHAR2(200) NULL,
        "UPDATE_DATE" TIMESTAMP(7) NULL,
        CONSTRAINT "FK_HRPAYADJ_EMP" FOREIGN KEY ("EMPLOYEE_CODE") REFERENCES "DEV_TEMPLATE"."HR_EMPLOYEE" ("EMPLOYEE_CODE"),
        CONSTRAINT "CK_HRPAYADJ_TYPE" CHECK ("ADJUSTMENT_TYPE" IN (''EARNING'', ''DEDUCTION'')),
        CONSTRAINT "CK_HRPAYADJ_STATUS" CHECK ("STATUS" IN (''PENDING'', ''APPROVED'', ''PROCESSED'', ''REJECTED''))
    )';
EXCEPTION
    WHEN OTHERS THEN
        IF SQLCODE != -955 THEN -- ORA-00955: name is already used by an existing object
            RAISE;
        ELSE
            DBMS_OUTPUT.PUT_LINE('Table DEV_TEMPLATE.HR_PAYROLL_ADJUSTMENT already exists.');
        END IF;
END;
/

BEGIN
    EXECUTE IMMEDIATE 'CREATE INDEX "DEV_TEMPLATE"."IX_HRPAYADJ_EMP_PER" ON "DEV_TEMPLATE"."HR_PAYROLL_ADJUSTMENT" ("COMPANY_ID", "EMPLOYEE_CODE", "PAY_PERIOD")';
EXCEPTION
    WHEN OTHERS THEN
        IF SQLCODE != -955 AND SQLCODE != -1408 THEN
            RAISE;
        END IF;
END;
/

BEGIN
    EXECUTE IMMEDIATE 'CREATE INDEX "DEV_TEMPLATE"."IX_HRPAYADJ_STATUS" ON "DEV_TEMPLATE"."HR_PAYROLL_ADJUSTMENT" ("STATUS")';
EXCEPTION
    WHEN OTHERS THEN
        IF SQLCODE != -955 AND SQLCODE != -1408 THEN
            RAISE;
        END IF;
END;
/

PROMPT DEV_TEMPLATE.HR_PAYROLL_ADJUSTMENT created successfully.
EXIT;
